"""
Classes for managing the items in a [`TrustableGraph`][trudag.dotstop.core.graph.TrustableGraph].
"""

import base64
import hashlib
import logging
import re
from dataclasses import dataclass
from functools import cached_property
from pathlib import Path
from typing import Any, Callable

import schema
import yaml

from trudag.dotstop.core.constants import ITEM_SEPARATOR
from trudag.dotstop.core.exception import (
    ArtifactError,
    ItemError,
    map_and_raise,
)
from trudag.dotstop.core.fallacy import Fallacy
from trudag.dotstop.core.reference import (
    BaseReference,
    ReferenceBuilder,
    ResolvedReference,
)
from trudag.dotstop.core.validator import Validator

logger = logging.getLogger(__name__)

_ITEM_SCORE_SCHEMA = schema.Schema(schema.Or({str: float}, float))


def map_and_raise_itemerror(
    prefix: str, *map_from: type[Exception]
) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def map_to_itemerror(err: type[Exception], *args, **kwargs):
        if not args:
            raise TypeError(
                "map_and_raise_itemerror applies to functions with a Item as the first argument. Got no arguments."
            )
        if not isinstance(args[0], Item):
            err_msg = f"map_and_raise_itemerror applies to functions with a Item as the first argument. Got argument of type {type(args[0])}."
            raise TypeError(err_msg)
        item = args[0]
        err_msg = f"{prefix + ': ' if prefix else ''}{item}: {err}"
        mapped_err = ItemError(err_msg)
        mapped_err.__cause__ = err
        return mapped_err

    return map_and_raise(map_to_itemerror, *map_from)


@dataclass
class ItemOrder:
    """
    Storage for item ordering properties.
    """

    # Last ascii character.
    # Items with undefined group will be ordered last.
    FINAL_GROUP = "~"

    group: str | None
    priority: list[int] | None

    def __init__(self, group: str | None, order: list[int] | None) -> None:
        self.group = group or ItemOrder.FINAL_GROUP
        self.priority = order or [0]


class Item:
    """
    A representation for a falsifiable statement and its associated properties.
    """

    def __init__(
        self,
        name: str,
        text: str = "",
        normative: bool = True,
        unresolved_references: list[BaseReference] | None = None,
        resolved_references: list[ResolvedReference] | None = None,
        validator_config: dict | None = None,
        sme_scores: dict[str, float] | float | None = None,
        fallacies: dict[str, Fallacy] | None = None,
        order: ItemOrder | None = None,
    ) -> None:
        self._name = name
        self._text = text
        self._normative = normative
        self._unresolved_references = unresolved_references or []
        self._resolved_references = resolved_references or []
        self._validator_config = validator_config
        self._sme_scores = sme_scores
        self._fallacies = fallacies or {}
        self._order = order or ItemOrder(None, None)

    @cached_property
    def sha256(self) -> bytes:
        """
        The sha256 digest of the item.
        """
        hash = hashlib.sha256()
        hash.update(self._name.encode())
        hash.update(self._text.encode())
        hash.update(self._normative.to_bytes(1, "little"))
        for reference in self.references():
            hash.update(reference.sha.encode())
        return hash.digest()

    @property
    def sha(self) -> str:
        "The sha256 checksum of the item."
        return self.sha256.hex()

    def sha_link(self, child: "Item") -> str:
        """
        A sha256 checksum of the link between two items.
        """
        hash = hashlib.sha256()
        hash.update(self.sha256 + child.sha256)
        return hash.hexdigest()

    @property
    def name(self) -> str:
        """
        The name of the item constructed from two parts, separated by a hyphen: `DOCUMENT-ID`

        - `DOCUMENT` is the document prefix and may contain any alphanumeric or special character expect `.` and `"`.
        Items with the same document prefix are grouped together in a [`TrustableGraph`][trudag.dotstop.core.graph.TrustableGraph].
        - `ID` is used to uniquely identify the item within a document. ID may contain any alphanumeric or special character except `.` and `-`.

        Example:
            Item with a name TSF-ITEM_1 is within the TSF document, uniquely identified in thist document as ITEM_1.
        """
        return self._name

    def add_namespace(self, namespace: str) -> None:
        """
        Namespaces the item by prepending its name with the namespace name, followed by a `.`.
        """
        self._name = f"{namespace}.{self._name}"

    @property
    def document(self) -> str:
        """
        Document group the item belongs to.
        """
        return ITEM_SEPARATOR.join(self.name.split(ITEM_SEPARATOR)[0:-1])

    def header(self, include_name: bool = True) -> str:
        """
        A short text summary of the item, containing more information than the name.

        Args:
            include_name(bool, optional): Prepend the item's name to the header.
        """
        splits = self._text.split("\n\n")
        if not splits:
            raise ItemError(f"Cannot get header for body-less item: {self.name}")
        name_prefix = f"{self.name}: " if include_name else ""
        return name_prefix + splits[0].replace("\n", " ").strip()

    @property
    def text(self) -> str:
        """
        The statement associated with a normative item.  If the item is not normative this can be any text.
        """
        return self._text

    @property
    def normative(self) -> bool:
        """
        Whether the item represents a normative statement.
        """
        return self._normative

    @property
    def sme_scores(self) -> dict[str, float] | None:
        if not self._sme_scores or isinstance(self._sme_scores, float):
            logger.debug(f"item {self.name} has no sme score")
            return None
        return self._sme_scores

    def references(self) -> list[ResolvedReference]:
        """
        Returns references in resolved form.
        """
        # Lazily resolve any unresolved references.
        if self._unresolved_references:
            self._resolved_references.extend(
                ref.resolve() for ref in self._unresolved_references
            )
            self._unresolved_references.clear()
        return self._resolved_references

    def fallacies(self) -> dict[str, Fallacy]:
        return self._fallacies

    def validation(self, validator: Validator) -> dict[str, Any]:
        """
        Computes the validator score for the item if there exists a validator config and
        returns the validation result object.
        """
        validation = {}
        if self._validator_config:
            score, logs, docstring = validator.validate(
                self._validator_config["type"], self._validator_config["configuration"]
            )
            validation.update(
                {
                    "evidence": self._validator_config,
                    "score": score,
                    "logs": logs,
                    "docstring": docstring,
                }
            )

        return validation

    @property
    def score(self) -> float | None:
        if self._sme_scores is None:
            logger.debug(f"item {self.name} has no managed score")
            return None
        if isinstance(self._sme_scores, float):
            return self._sme_scores
        return sum(self._sme_scores.values()) / len(self._sme_scores.values())

    def serialise(self) -> dict:
        """
        Serialise the item into a dictionary.
        """
        return {
            "name": self._name,
            "text": self._text,
            "normative": self._normative,
            "resolved_references": [ref.serialise() for ref in self.references()],
            "sha": self.sha,
        }

    def serialise_as_need(self) -> dict:
        """
        Serialise the item, as a need, into a dictionary.
        """
        if self._validator_config or self.sme_scores:
            err_msg = (
                f"Needs item {self.name} should not have evidence or associated score."
            )
            raise ArtifactError(err_msg)
        return {
            "name": self._name,
            "text": self._text,
            "normative": self._normative,
            "resolved_references": [ref.serialise() for ref in self.references()],
        }

    def deserialise(data: dict) -> "Item":
        """
        Deserialise a dictionary of data into an item.
        """
        resolved_references = []
        if refs := data.get("resolved_references"):
            resolved_references.extend(
                [ResolvedReference.deserialise(ref) for ref in refs]
            )
        return Item(
            name=data["name"],
            text=data["text"],
            normative=data["normative"],
            unresolved_references=[],
            resolved_references=resolved_references,
        )

    def __lt__(self, other: "Item") -> bool:
        def _none_sort_key(value):
            return (value is not None, value)

        return (
            _none_sort_key(self._order.group),
            _none_sort_key(self._order.priority),
            _none_sort_key(self.name),
        ) < (
            _none_sort_key(other._order.group),
            _none_sort_key(other._order.priority),
            _none_sort_key(other.name),
        )

    def __str__(self) -> str:
        return self._name


_FRONTMATTER_SCHEMA = schema.Schema(
    {
        "normative": bool,
        schema.Optional("references"): list[dict],
        schema.Optional("resolved_references"): [
            {
                "type": schema.And(str, len),
                "sha": schema.And(str, len),
                "origin": str,
                "text_content": bytes,
            }
        ],
        schema.Optional("fallacies"): {
            str: {"description": str, "reference": dict},
        },
        schema.Optional("evidence"): {"type": str, "configuration": dict},
        schema.Optional("score"): schema.Or(float, schema.Schema({str: float})),
        # Define item ordering.
        schema.Optional("level"): schema.And(
            schema.Use(str), lambda x: x if re.match(r"[0-9]+(\.[0-9]+)*", x) else None
        ),
        schema.Optional("publish"): {
            schema.Optional("group"): str,
            schema.Optional("order"): int,
        },
    },
    ignore_extra_keys=True,
)


def item_from_markdown(
    item_name: str,
    md_content: str,
    reference_builder: ReferenceBuilder = ReferenceBuilder(),
) -> Item:
    """
    Creates an item from markdown content.
    """
    front_delimiter = "---"
    splits = md_content.split(front_delimiter, 2)
    if len(splits) <= 2 or not splits[1]:
        err_msg = f"Cannot build item from markdown {item_name} without frontmatter and content."
        raise ItemError(err_msg)
    try:
        yaml_frontmatter = yaml.safe_load(splits[1])
        frontmatter = _FRONTMATTER_SCHEMA.validate(yaml_frontmatter)
    except Exception as err:
        raise ItemError(f"{item_name}: Invalid frontmatter:\n{err}") from err

    if publish_order := frontmatter.get("publish"):
        item_order = ItemOrder(publish_order.get("group"), [publish_order.get("order")])
    elif level := frontmatter.get("level"):
        item_order = ItemOrder(None, list(map(int, level.split("."))))
    else:
        item_order = ItemOrder(None, None)

    references = [
        reference_builder.build(ref) for ref in frontmatter.get("references", [])
    ]
    resolved_references = [
        ResolvedReference.deserialise(ref)
        for ref in frontmatter.get("resolved_references", [])
    ]

    return Item(
        name=item_name,
        text=splits[2].strip("\n"),
        normative=frontmatter["normative"],
        unresolved_references=references,
        resolved_references=resolved_references,
        validator_config=frontmatter.get("evidence"),
        sme_scores=frontmatter.get("score"),
        order=item_order,
    )


def need_as_markdown(item: "Item", namespace: str) -> str:
    """
    Creates a markdown string for a needs item.
    """
    need_data = item.serialise_as_need()
    frontmatter = {}
    frontmatter["normative"] = need_data["normative"]
    if refs := need_data["resolved_references"]:
        resolved_references = [
            {
                "type": ref["type"],
                "sha": ref["sha"],
                "origin": f"{namespace}://{ref['origin']}",
                "text_content": base64.b64encode(ref["text_content"].encode()),
            }
            for ref in refs
        ]
        frontmatter["resolved_references"] = resolved_references
    return f"---\n{yaml.safe_dump(frontmatter)}\n---\n\n{need_data['text']}"


def create_default_item_markdown(name: str, dir: Path) -> Item:
    """
    Create a default item, writes it in markdown in dir.
    """
    file_name = dir / f"{name}.md"
    if file_name.exists():
        err_msg = f"Cannot create markdown item {name}, file {file_name} already exists"
        raise FileExistsError(err_msg)

    item_content = f"---\n{yaml.safe_dump({'normative': True})}---\n\n"
    with file_name.open("w") as f:
        f.write(item_content)

    return item_from_markdown(name, item_content)
